  let dwv = b * (1.0 + B * B) / (1.0 - B * b);
  let dP = BU * dwu + BV * dwv;

  // normalize(Pc + dP) - normalize(Pc), stable as dP -> 0
  let inv = 1.0 / lenPc;
  let sq = (2.0 * dot(Pc, dP) + dot(dP, dP)) * inv * inv;
  let k = sq / (1.0 + sqrt(1.0 + sq));   // sqrt(1+s) - 1, without cancellation
